// Token arrives only in Telegram's HTTPS secret header. Its SHA-256 must match
// the fingerprint generated by the repository's existing secret; never log it.
const CREDENTIAL_SHA256 = 'f95e44a0ffae4d0a32076a3080987262c08459f9068394366f1238fc7d7dd420';
const OWNER = '1015720586';
const REPO='nandurpm/electro';
const API='https://api.github.com/repos/'+REPO;
const json=(v:unknown,status=200)=>new Response(JSON.stringify(v),{status,headers:{'content-type':'application/json','cache-control':'no-store'}});
const esc=(s:unknown)=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const menu={keyboard:[[{text:'📲 Download APK'},{text:'🆕 Latest Version'}],[{text:'🧮 Quick Tools'}],[{text:'📦 Source Code'},{text:'📚 Releases'}],[{text:'🟢 Build Status'},{text:'📝 What’s New'}],[{text:'🏠 Main Menu'},{text:'ℹ️ About & Privacy'}]],resize_keyboard:true};
const aliases:Record<string,string>={'📲 Download APK':'/apk','🆕 Latest Version':'/version','🧮 Quick Tools':'/tools','📦 Source Code':'/source','📚 Releases':'/releases','🟢 Build Status':'/status','📝 What’s New':'/changelog','🏠 Main Menu':'/menu','ℹ️ About & Privacy':'/about','❓ Help':'/help'};
const commands=[['start','Open your private ELECTRO menu'],['menu','Main menu'],['apk','Latest Android APK'],['version','Latest release'],['source','Source ZIP'],['releases','Release history'],['status','Build status'],['tools','Quick electrical calculations'],['changelog','Latest release notes'],['about','Privacy and response times'],['help','Command help']].map(([command,description])=>({command,description}));
async function digest(s:string){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),b=>b.toString(16).padStart(2,'0')).join('');}
function authorized(u:any){const m=u.message;return m?.chat?.type==='private'&&String(m.chat.id)===OWNER&&String(m.from?.id)===OWNER&&!m.from?.is_bot;}
async function tg(token:string,method:string,body:any){
 const r=await fetch('https://api.telegram.org/bot'+token+'/'+method,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(25000)});
 const d=await r.json();if(!d.ok)throw Error('telegram_failed');return d.result;
}
async function send(token:string,text:string,reply_markup:any=menu){return tg(token,'sendMessage',{chat_id:OWNER,text,parse_mode:'HTML',reply_markup,link_preview_options:{is_disabled:true}});}
let cached:any,cacheUntil=0;
async function github(path:string){const r=await fetch(API+path,{headers:{'accept':'application/vnd.github+json','user-agent':'electro-private-webhook'},signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('github_unavailable');return r.json();}
async function latest(){if(Date.now()>cacheUntil){cached=await github('/releases/latest');cacheUntil=Date.now()+60000;}return cached;}
function quick(text:string){
 const guide='🧮 <b>QUICK TOOLS</b>\n\n/ohm 230 46 — V and Ω → A\n/power 230 5 — V and A → W (DC/resistive)\n/threephase 415 10 0.85 — line V, A, PF → input kW\n\nUse SI units. Motor output also requires efficiency. These estimates do not select cables or protection.';
 const [cmd,...args]=text.split(/\s+/);if(cmd==='/tools')return guide;
 const v=args.map(Number);if(v.length!==(cmd==='/threephase'?3:2)||v.some(n=>!Number.isFinite(n)||n<=0)||(cmd==='/threephase'&&v[2]>1))return '⚠️ Check values: positive numbers only; PF ≤ 1.\n\n'+guide;
 const result=cmd==='/ohm'?v[0]/v[1]:cmd==='/power'?v[0]*v[1]:Math.sqrt(3)*v[0]*v[1]*v[2]/1000;
 if(!Number.isFinite(result))return '⚠️ Result exceeds the supported range.\n\n'+guide;
 return '<b>'+result.toPrecision(5)+' '+(cmd==='/ohm'?'A':cmd==='/power'?'W':'kW input')+'</b>\n\n'+guide;
}
async function document(token:string,release:any,suffix:string){
 const asset=release.assets?.find((a:any)=>String(a.name).toLowerCase().endsWith(suffix)&&a.size<=45*1024*1024&&String(a.browser_download_url).startsWith('https://github.com/'+REPO+'/releases/download/'));
 if(!asset){await send(token,'No matching download is attached to this release.');return;}
 // Upload APK bytes: Telegram URL-based sendDocument only supports PDF/ZIP.
 const r=await fetch(asset.browser_download_url,{signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error('download_failed');
 if(Number(r.headers.get('content-length')||0)>45*1024*1024)throw Error('download_too_large');
 const bytes=await r.arrayBuffer();if(bytes.byteLength>45*1024*1024)throw Error('download_too_large');
 const body=new FormData();body.append('chat_id',OWNER);body.append('document',new Blob([bytes]),asset.name);body.append('caption','ELECTRO '+release.tag_name);
 const sent=await fetch('https://api.telegram.org/bot'+token+'/sendDocument',{method:'POST',body,signal:AbortSignal.timeout(40000)});if(!(await sent.json()).ok)throw Error('upload_failed');
}
async function handle(text:string,token:string){
 text=aliases[text.trim()]||text.trim();const cmd=text.split(/\s+/)[0].split('@')[0].toLowerCase();
 if(['/tools','/ohm','/power','/threephase'].includes(cmd)){await send(token,quick(text.replace(/^\S+/,cmd)));return;}
 if(['/menu','/start','/help'].includes(cmd)){await send(token,'⚡ <b>ELECTRO</b>\nYour private electronics toolkit.\n\n/apk · /version · /source · /releases\n/tools · /changelog · /status\n\nReplies now arrive through a webhook. Choose a button below.');return;}
 if(cmd==='/about'){await send(token,'⚡ <b>ABOUT & PRIVACY</b>\nOnly your configured private account can use this bot.\n\nWebhook replies run on Supabase, without waiting for a scheduled GitHub check. Network and download times can still vary.');return;}
 if(cmd==='/status'){const data=await github('/actions/runs?per_page=3');await send(token,'🟢 <b>BUILD STATUS</b>\n'+data.workflow_runs.map((r:any)=>esc(r.name+' · '+(r.conclusion||r.status))).join('\n'));return;}
 if(cmd==='/releases'){const data=await github('/releases?per_page=5');await send(token,'📚 <b>RELEASES</b>\n'+data.map((r:any)=>'<a href="'+r.html_url+'">'+esc(r.tag_name)+'</a>').join('\n'));return;}
 if(['/apk','/source','/version','/changelog'].includes(cmd)){
  const r=await latest();if(cmd==='/apk'||cmd==='/source'){try{await document(token,r,cmd==='/apk'?'.apk':'-source.zip');}catch{await send(token,'The file upload is unavailable. Download from the release page:',{inline_keyboard:[[{text:'Open release downloads',url:r.html_url}]]});}return;}
  await send(token,cmd==='/version'?'⚡ <b>'+esc(r.tag_name)+'</b>\nPublished: '+esc(String(r.published_at).slice(0,10)):'📝 <b>'+esc(r.tag_name)+'</b>\n\n'+esc(String(r.body||'See release details.').slice(0,2800)),{inline_keyboard:[[{text:'Release details',url:r.html_url}],[{text:'Main menu',callback_data:'menu'}]]});return;
 }
 await send(token,'Choose a menu button or send /help.');
}
export async function handler(request:Request){
 if(request.method==='GET')return json({ok:true,mode:'webhook'});
 if(request.method!=='POST')return json({error:'method_not_allowed'},405);
 const credential=request.headers.get('x-telegram-bot-api-secret-token')||'';
 if(await digest(credential)!==CREDENTIAL_SHA256)return json({error:'forbidden'},403);
 if(!/^\d+_[A-Za-z0-9_-]+$/.test(credential))return json({error:'forbidden'},403);
 const split=credential.indexOf('_'),token=credential.slice(0,split)+':'+credential.slice(split+1);
 try{
  if(new URL(request.url).pathname.endsWith('/verify')){const me=await tg(token,'getMe',{});return json({ok:true,bot_id:me.id,mode:'webhook'});}
  const u=await request.json();
  if(u.callback_query){const c=u.callback_query;if(c.message?.chat?.type==='private'&&String(c.message.chat.id)===OWNER&&String(c.from?.id)===OWNER){await tg(token,'answerCallbackQuery',{callback_query_id:c.id});if(c.data==='menu')await handle('/menu',token);}return json({ok:true});}
  if(!authorized(u))return json({ok:true,ignored:true});
  if(typeof u.message.text==='string')await handle(u.message.text,token);
  return json({ok:true});
 }catch{return json({error:'request_failed'},500);}
}
Deno.serve(handler);
